import { ICONS } from "./icons.generated.js";
export const ICON_TYPES = ["normal", "duotone", "fill", "pixelated", "glass"];
let byId;
export function getIconById(id) {
    byId ??= new Map(ICONS.map((icon) => [icon.id, icon]));
    return byId.get(id);
}
export function availableTypes(icon) {
    return ICON_TYPES.filter((type) => icon.variants[type]);
}
export function searchIcons(query, limit = Number.POSITIVE_INFINITY) {
    const q = query.trim().toLowerCase();
    const matched = q
        ? ICONS.filter((icon) => icon.id.includes(q) || icon.name.toLowerCase().includes(q))
        : ICONS;
    return matched.slice(0, limit);
}
export function buildSvg(icon, type, size = 24) {
    const variant = icon.variants[type];
    if (!variant)
        return null;
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="${variant.viewBox}">${variant.markup}</svg>`;
}
